import json
G=[[9]*27 for _ in range(11)]
# 6x6 outline at rows 2..7, cols 1..6; fill even-sized interior with 2
for r in range(2,8):
    for c in range(1,7):
        if r in (2,7) or c in (1,6): G[r][c]=0
        else: G[r][c]=2
# 3x3 outline at rows 5..7, cols 9..11; odd-sized interior with 7
for r in range(5,8):
    for c in range(9,12):
        if r in (5,7) or c in (9,11): G[r][c]=6
        else: G[r][c]=7
# 7x7 outline at rows 1..7, cols 14..20; odd-sized interior with 7
for r in range(1,8):
    for c in range(14,21):
        if r in (1,7) or c in (14,20): G[r][c]=3
        else: G[r][c]=7
print(json.dumps(G))
